export function migrate(db, migrations = migrationsList) {
  db.exec('CREATE TABLE IF NOT EXISTS schema_migrations (id TEXT PRIMARY KEY, applied_at TEXT NOT NULL)');
  const applied = new Set(db.prepare('SELECT id FROM schema_migrations').all().map(r=>r.id));
  const run = db.transaction((m) => { m.up(db); db.prepare('INSERT INTO schema_migrations (id, applied_at) VALUES (?,?)').run(m.id, new Date().toISOString()); });
  for (const m of migrations) if (!applied.has(m.id)) run(m);
}
```
