export class ApiError extends Error { constructor(public status: number, message: string) }
export async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, { headers: {...}, ...init });
  const text = await res.text();
  let body: unknown = undefined;
  if (text) { try { body = JSON.parse(text) } catch { /* */ } }
  if (!res.ok) {
    const message = isErrorBody(body) ? body.error : `Request failed (${res.status})`;
    throw new ApiError(res.status, message);
  }
  return body as T;
}
export const api = {
  health: () => apiFetch<Health>('/api/health'),
