import path from 'node:path';
import Database from 'better-sqlite3';

/**
 * Open (creating parent directories when needed) the SQLite database used for
 * every persistent workbook fact. Foreign keys are enabled so that deleting a
 * workbook also removes its worksheets, cells and rules.
 */
export function openDatabase(databasePath) {
  if (databasePath !== ':memory:') {
    fs.mkdirSync(path.dirname(databasePath), { recursive: true });
  }
  const db = new Database(databasePath);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  return db;
}

/** Run `fn` inside a single SQLite transaction. Every application write uses this. */
export function inTransaction(db, fn) {
