/**
 * Apply every migration that has not been recorded yet. Running this on each
 * startup is safe and repeatable: already applied ids are skipped.
 */
export function migrate(db, migrations = defaultMigrations, now = () => new Date().toISOString()) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      id         TEXT PRIMARY KEY,
      applied_at TEXT NOT NULL
    );
  `);

  const applied = new Set(db.prepare('SELECT id FROM schema_migrations').all().map((row) => row.id));
  const appliedNow = [];

  for (const migration of migrations) {
    if (applied.has(migration.id)) continue;
    const run = db.transaction(() => {
      migration.up(db);
      db.prepare('INSERT INTO schema_migrations (id, applied_at) VALUES (?, ?)').run(migration.id, now());
    });
    run();
    appliedNow.push(migration.id);
  }

  return appliedNow;
}
