 */

export function listWorkbooks(db) {
  const rows = db
    .prepare('SELECT id, name, updated_at FROM workbooks ORDER BY updated_at DESC, name ASC')
    .all();
  return rows.map((row) => ({
    id: row.id,
    name: row.name,
    updatedAt: row.updated_at,
  }));
}

export function getWorkbook(db, workbookId) {
  const row = db
    .prepare('SELECT id, name, active_worksheet_id, created_at, updated_at FROM workbooks WHERE id = ?')
    .get(workbookId);
  if (!row) return null;
  return {
    id: row.id,
    name: row.name,
    activeWorksheetId: row.active_worksheet_id,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export function getWorkbookDetail(db, workbookId) {
  const workbook = getWorkbook(db, workbookId);
  if (!workbook) return null;

  const worksheetRows = db
    .prepare('SELECT * FROM worksheets WHERE workbook_id = ? ORDER BY position ASC')
    .all(workbookId);

  const selectCells = db.prepare('SELECT row, col, value FROM cells WHERE worksheet_id = ? ORDER BY row, col');
  const selectValidations = db.prepare('SELECT * FROM validations WHERE worksheet_id = ? ORDER BY position ASC');

  const worksheets = worksheetRows.map((worksheet) => ({
    id: worksheet.id,
    name: worksheet.name,
    position: worksheet.position,
    isActive: worksheet.id === workbook.activeWorksheetId,
    lastSelectedCell: { row: worksheet.last_selected_row, col: worksheet.last_selected_col },
    lastSelectionRect: {
      anchor: { row: worksheet.selection_anchor_row, col: worksheet.selection_anchor_col },
      focus: { row: worksheet.selection_focus_row, col: worksheet.selection_focus_col },
    },
    cells: selectCells.all(worksheet.id).map((cell) => ({
      row: cell.row,
      col: cell.col,
      value: cell.value,
      display: cell.value,
    })),
    validations: selectValidations.all(worksheet.id).map((validation) => ({
      id: validation.id,
      kind: validation.kind,
      minValue: validation.min_value,
      maxValue: validation.max_value,
      options: validation.options_json ? JSON.parse(validation.options_json) : null,
      range: {
        start: { row: validation.start_row, col: validation.start_col },
        end: { row: validation.end_row, col: validation.end_col },
      },
    })),
  }));

  return {
    workbook: {
      id: workbook.id,
      name: workbook.name,
      activeWorksheetId: workbook.activeWorksheetId,
      updatedAt: workbook.updatedAt,
    },
    worksheets,
  };
}
