/**
 * Uniform API error handling.
 *
 * Every failing `/api` response is `{ "error": "<message>" }` with a 4xx/5xx
 * status, matching the contract published in docs/api-contract.md.
 */
export class ApiError extends Error {
  constructor(status, message, { expose = true } = {}) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.expose = expose;
  }
}

export function apiNotFoundHandler(req, res) {
  res.status(404).json({ error: `Not found: ${req.method} ${req.originalUrl}` });
}

// eslint-disable-next-line no-unused-vars -- Express identifies error middleware by arity
export function errorHandler(error, req, res, next) {
  const status = Number.isInteger(error?.status) ? error.status : 500;
  const expose = error instanceof ApiError ? error.expose : false;
  const message = expose ? error.message : 'Internal server error';
  if (status >= 500) {
    console.error('[api] unhandled error', error);
  }
  res.status(status).json({ error: message });
}
