/**
 * Build the Express application: the `/api` surface plus the built frontend.
 *
 * Static hosting and the SPA fallback mean a direct visit to `/wb/<id>` (or a
 * refresh there) serves `frontend/dist/index.html` instead of a 404.
 */
export function createApp({ db, frontendDist, logger = console }) {
  const app = express();
  app.disable('x-powered-by');
  app.use(express.json({ limit: '5mb' }));

  app.get('/api/health', (req, res) => {
    res.json({ status: 'ok' });
  });
  app.use('/api/workbooks', createWorkbooksRouter(db));
  app.use('/api', apiNotFoundHandler);

  const indexHtml = frontendDist ? path.join(frontendDist, 'index.html') : null;
  if (indexHtml && fs.existsSync(indexHtml)) {
    app.use(express.static(frontendDist));
    app.get(/^(?!\/api).*/, (req, res, next) => {
      res.sendFile(indexHtml, (error) => (error ? next(error) : undefined));
    });
  } else {
    logger.warn(`[backend] frontend build not found at ${frontendDist}; serve only /api until it is built`);
    app.get('/', (req, res) => {
      res
        .status(503)
        .type('text/plain')
        .send('Frontend build not found. Run "npm run build" in frontend/ and restart the server.');
    });
  }

  app.use(errorHandler);
  return app;
}
