import { afterEach, describe, expect, it } from 'vitest';
import { openDatabase } from '../src/db/index.js';
import { migrate } from '../src/db/migrate.js';
import { SEED_KEY, SEED_WORKBOOK_ID, seedDatabase } from '../src/db/seed.js';
import { createTempDatabaseFile, silentLogger } from './helpers.js';
import { createApp } from '../src/app.js';

const freshDatabases = [];

function newDatabase() {
  const { dir, file } = createTempDatabaseFile();
  const db = openDatabase(file);
  migrate(db);
  freshDatabases.push({ db, dir });
  return { db, dir, file };
}

afterEach(() => {
  while (freshDatabases.length) {
    const { db, dir } = freshDatabases.pop();
    if (db.open) db.close();
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

describe('seed idempotency', () => {
  it('creates one workbook, its two worksheets and the seeded values on first run', () => {
    const { db } = newDatabase();
    expect(seedDatabase(db)).toMatchObject({ applied: true, workbookId: SEED_WORKBOOK_ID });

    expect(db.prepare('SELECT COUNT(*) AS count FROM workbooks').get().count).toBe(1);
    expect(db.prepare('SELECT COUNT(*) AS count FROM worksheets').get().count).toBe(2);
    expect(db.prepare('SELECT COUNT(*) AS count FROM cells').get().count).toBe(6);
    expect(db.prepare('SELECT value FROM app_meta WHERE key = ?').get(SEED_KEY)).toBeTruthy();
  });

  it('does not duplicate anything when run again on the same database', () => {
    const { db } = newDatabase();
    seedDatabase(db);
    const before = db.prepare('SELECT id, name, position FROM worksheets ORDER BY position').all();

    expect(seedDatabase(db)).toMatchObject({ applied: false });

    expect(db.prepare('SELECT COUNT(*) AS count FROM workbooks').get().count).toBe(1);
    expect(db.prepare('SELECT COUNT(*) AS count FROM cells').get().count).toBe(6);
    expect(db.prepare('SELECT id, name, position FROM worksheets ORDER BY position').all()).toEqual(before);
  });

  it('does not overwrite data changed by the user after the seed', () => {
    const { db, file } = newDatabase();
    seedDatabase(db);

    const sheet1 = db.prepare('SELECT id FROM worksheets WHERE workbook_id = ? ORDER BY position').get(SEED_WORKBOOK_ID);
    db.prepare('UPDATE workbooks SET name = ? WHERE id = ?').run('Renamed by user', SEED_WORKBOOK_ID);
    db.prepare('UPDATE cells SET value = ? WHERE worksheet_id = ? AND row = 0 AND col = 0').run('Changed', sheet1.id);
    db.prepare('DELETE FROM validations').run();
    db.close();

    const reopened = openDatabase(file);
    migrate(reopened);
    expect(seedDatabase(reopened)).toMatchObject({ applied: false });

    expect(reopened.prepare('SELECT name FROM workbooks WHERE id = ?').get(SEED_WORKBOOK_ID).name).toBe('Renamed by user');
    expect(
      reopened.prepare('SELECT value FROM cells WHERE worksheet_id = ? AND row = 0 AND col = 0').get(sheet1.id).value,
    ).toBe('Changed');
    expect(reopened.prepare('SELECT COUNT(*) AS count FROM validations').get().count).toBe(0);
    reopened.close();
  });

  it('keeps a single workbook after a restart applies migrations and seed again', () => {
    const { db, file } = newDatabase();
    seedDatabase(db);
    db.close();

    for (let restart = 0; restart < 2; restart += 1) {
      const reopened = openDatabase(file);
      expect(migrate(reopened)).toEqual([]);
      seedDatabase(reopened);
      expect(reopened.prepare('SELECT COUNT(*) AS count FROM workbooks').get().count).toBe(1);
      expect(reopened.prepare('SELECT COUNT(*) AS count FROM worksheets').get().count).toBe(2);
      reopened.close();
    }
  });

  it('serves the seeded workbook through the app right after start', async () => {
    const { db } = newDatabase();
    seedDatabase(db);
    const { createServer } = await import('node:http');
    const app = createApp({ db, frontendDist: '/nonexistent-dist', logger: silentLogger });
    const server = createServer(app).listen(0, '127.0.0.1');
    await new Promise((resolve) => server.once('listening', resolve));
    const { port } = server.address();
    try {
      const body = await (await fetch(`http://127.0.0.1:${port}/api/workbooks`)).json();
      expect(body.workbooks.map((workbook) => workbook.name)).toContain('Q3 Sales');
    } finally {
      await new Promise((resolve) => server.close(resolve));
    }
  });
});
