 * Timestamp rendering.
 *
 * The home page and the editor must show the same value for the same workbook,
 * so every screen formats `updatedAt` through this single helper.
 */
export function formatUpdatedAt(isoTimestamp: string): string {
  const date = new Date(isoTimestamp);
  if (Number.isNaN(date.getTime())) return isoTimestamp;
  const pad = (value: number) => String(value).padStart(2, '0');
  return (
    `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())} ` +
    `${pad(date.getUTCHours())}:${pad(date.getUTCMinutes())}:${pad(date.getUTCSeconds())} UTC`
  );
}

/** Prefix used by every record that shows a last-updated value. */
export function lastUpdatedText(isoTimestamp: string): string {
  return `Last updated: ${formatUpdatedAt(isoTimestamp)}`;
}
