/** Spreadsheet column label: 0 → "A", 25 → "Z", 26 → "AA". */
export function columnLabel(col: number): string {
  let label = '';
  let remaining = col;
  while (remaining >= 0) {
    label = String.fromCharCode(65 + (remaining % 26)) + label;
    remaining = Math.floor(remaining / 26) - 1;
  }
  return label;
}

/** Cell coordinate used as the accessible name of a grid cell, e.g. "A1". */
export function cellAddress(row: number, col: number): string {
  return `${columnLabel(col)}${row + 1}`;
}

export interface RectBounds {
  minRow: number;
  maxRow: number;
  minCol: number;
  maxCol: number;
}

export function rectBounds(rect: SelectionRect): RectBounds {
  return {
    minRow: Math.min(rect.anchor.row, rect.focus.row),
    maxRow: Math.max(rect.anchor.row, rect.focus.row),
    minCol: Math.min(rect.anchor.col, rect.focus.col),
    maxCol: Math.max(rect.anchor.col, rect.focus.col),
  };
}

export function isWithinBounds(bounds: RectBounds, point: SelectionPoint): boolean {
  return (
    point.row >= bounds.minRow &&
    point.row <= bounds.maxRow &&
    point.col >= bounds.minCol &&
    point.col <= bounds.maxCol
  );
}
