import { cellAddress, columnLabel, isWithinBounds, rectBounds } from '../utils/grid';

export interface WorkbookGridProps {
  cells: CellValue[];
  selectedCell: SelectionPoint;
  selectionRect: SelectionRect;
  label?: string;
  minimumRows?: number;
  minimumCols?: number;
}

/**
 * Read-only foundation grid.
 *
 * It already follows the shared ARIA contract (design-root.md §2.1): the grid
 * is named "Worksheet grid" and is multi-selectable, cells are `gridcell` with
 * their coordinate as accessible name, and exactly the cells inside the
 * selection rectangle expose aria-selected="true". Editing, keyboard movement
 * and richer selection belong to the grid editing task, which extends this
 * component rather than replacing the contract.
 */
export default function WorkbookGrid({
  cells,
  selectedCell,
  selectionRect,
  label = 'Worksheet grid',
  minimumRows = 10,
  minimumCols = 4,
}: WorkbookGridProps) {
  const maxRow = cells.reduce((max, cell) => Math.max(max, cell.row), 0);
  const maxCol = cells.reduce((max, cell) => Math.max(max, cell.col), 0);
  const rowCount = Math.max(minimumRows, maxRow + 1, selectedCell.row + 1);
  const colCount = Math.max(minimumCols, maxCol + 1, selectedCell.col + 1);
  const bounds = rectBounds(selectionRect);
  const displayByAddress = new Map(cells.map((cell) => [cellAddress(cell.row, cell.col), cell.display]));
  const rows = Array.from({ length: rowCount }, (_, index) => index);
  const cols = Array.from({ length: colCount }, (_, index) => index);

  return (
    <table
      role="grid"
      aria-label={label}
      aria-multiselectable="true"
      className="border-collapse bg-surface text-ink"
    >
      <thead>
        <tr role="row">
          <th
            role="columnheader"
            aria-label="Select all"
            className="w-10 border border-border bg-header px-2 py-1 text-xs text-ink-muted"
          />
          {cols.map((col) => (
            <th
              key={col}
              role="columnheader"
              aria-label={columnLabel(col)}
              className="min-w-24 border border-border bg-header px-2 py-1 text-xs font-normal text-ink-muted"
            >
              {columnLabel(col)}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={row} role="row">
            <th
              role="rowheader"
              aria-label={String(row + 1)}
              className="border border-border bg-header px-2 py-1 text-xs font-normal text-ink-muted"
            >
              {row + 1}
            </th>
            {cols.map((col) => {
              const address = cellAddress(row, col);
              const selected = isWithinBounds(bounds, { row, col });
              const isCurrent = selectedCell.row === row && selectedCell.col === col;
              return (
                <td
                  key={col}
                  role="gridcell"
                  aria-label={address}
                  aria-selected={selected}
                  className={`h-7 min-w-24 border border-border px-2 py-1 align-middle ${
                    isCurrent ? 'bg-accent-soft' : 'bg-surface'
                  }`}
                >
                  {displayByAddress.get(address) ?? ''}
                </td>
              );
            })}
          </tr>
        ))}
      </tbody>
    </table>
  );
}
