import { Link, useParams } from 'react-router-dom';
import { api } from '../api/client';
import type { WorkbookDetail } from '../api/types';
import WorkbookGrid from '../components/WorkbookGrid';
import { lastUpdatedText } from '../utils/format';

type LoadState =
  | { status: 'loading' }
  | { status: 'ready'; detail: WorkbookDetail }
  | { status: 'error'; message: string };

/**
 * Workbook editor.
 *
 * The read-only foundation shows the persistent workbook state: title, the same
 * "Last updated" value as the home page, the worksheet tabs in stored order and
 * the selected worksheet's grid values. Worksheet switching is in-session only
 * here; persisting the active worksheet and the selection belongs to the
 * workbook/worksheet tasks.
 */
export default function EditorPage() {
  const { workbookId = '' } = useParams();
  const [state, setState] = useState<LoadState>({ status: 'loading' });
  const [selectedWorksheetId, setSelectedWorksheetId] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setState({ status: 'loading' });
    setSelectedWorksheetId(null);
    api
      .getWorkbook(workbookId)
      .then((detail) => {
        if (!cancelled) setState({ status: 'ready', detail });
      })
      .catch((error: unknown) => {
        if (!cancelled) {
          setState({ status: 'error', message: error instanceof Error ? error.message : 'Failed to open workbook' });
        }
      });
    return () => {
      cancelled = true;
    };
  }, [workbookId]);

  if (state.status === 'loading') {
    return (
      <main className="p-8">
        <p role="status">Loading workbook…</p>
      </main>
    );
  }

  if (state.status === 'error') {
    return (
      <main className="p-8">
        <p role="alert" className="text-danger">
          {state.message}
        </p>
        <p className="mt-4">
          <Link to="/" className="sw-link">
            Back to workbooks
          </Link>
        </p>
      </main>
    );
  }

  const { workbook, worksheets } = state.detail;
  const activeWorksheet =
    worksheets.find((worksheet) => worksheet.id === selectedWorksheetId) ??
    worksheets.find((worksheet) => worksheet.isActive) ??
    worksheets[0];

  return (
    <main className="flex h-full flex-col">
      <header className="flex items-baseline gap-4 border-b border-border bg-surface px-6 py-3">
        <h1 className="text-xl">{workbook.name}</h1>
        <span className="text-ink-muted">{lastUpdatedText(workbook.updatedAt)}</span>
      </header>

      {activeWorksheet ? (
        <>
          <div role="tablist" aria-label="Worksheets" className="flex gap-1 border-b border-border bg-header px-4 pt-2">
            {worksheets.map((worksheet) => {
              const isActive = worksheet.id === activeWorksheet.id;
              return (
                <button
                  key={worksheet.id}
                  type="button"
                  role="tab"
                  id={`worksheet-tab-${worksheet.id}`}
                  aria-selected={isActive}
                  aria-controls={`worksheet-panel-${worksheet.id}`}
                  tabIndex={isActive ? 0 : -1}
                  onClick={() => setSelectedWorksheetId(worksheet.id)}
                  className={`rounded-t px-3 py-1.5 sw-focus ${
                    isActive ? 'bg-surface text-ink' : 'bg-transparent text-ink-muted hover:bg-accent-soft'
                  }`}
                >
                  {worksheet.name}
                </button>
              );
            })}
          </div>

          <div
            role="tabpanel"
            id={`worksheet-panel-${activeWorksheet.id}`}
            aria-labelledby={`worksheet-tab-${activeWorksheet.id}`}
            className="flex-1 overflow-auto p-4"
          >
            <WorkbookGrid
              cells={activeWorksheet.cells}
              selectedCell={activeWorksheet.lastSelectedCell}
              selectionRect={activeWorksheet.lastSelectionRect}
            />
          </div>
        </>
      ) : (
        <p role="status" className="p-6">
          This workbook has no worksheets.
        </p>
      )}
    </main>
  );
}
