  it('returns the parsed JSON body for a successful response', async () => {
    stubFetch();
    fetchMock.mockResolvedValue(jsonResponse(200, { status: 'ok' }));
    await expect(apiFetch('/api/health')).resolves.toEqual({ status: 'ok' });
    expect(fetchMock).toHaveBeenCalledWith('/api/health', expect.objectContaining({ headers: expect.any(Object) }));
  });

  it('surfaces the shared { error } message with the HTTP status', async () => {
    stubFetch();
    fetchMock.mockResolvedValue(jsonResponse(404, { error: 'Workbook not found' }));

    await expect(apiFetch('/api/workbooks/nope')).rejects.toMatchObject({
      name: 'ApiError',
      status: 404,
      message: 'Workbook not found',
    });
  });

  it('falls back to a status message when the error body is not the shared shape', async () => {
    stubFetch();
    fetchMock.mockResolvedValue(emptyResponse(500));

    const error = await apiFetch('/api/workbooks').catch((caught: unknown) => caught);
    expect(error).toBeInstanceOf(ApiError);
    expect((error as ApiError).status).toBe(500);
    expect((error as ApiError).message).toBe('Request failed with status 500');
  });

  it('reports transport failures as ApiError instead of throwing a raw error', async () => {
    stubFetch();
    fetchMock.mockRejectedValue(new TypeError('Failed to fetch'));

    await expect(apiFetch('/api/workbooks')).rejects.toMatchObject({
      name: 'ApiError',
      status: 0,
      message: 'Failed to fetch',
    });
  });
});

describe('api.listWorkbooks / api.getWorkbook', () => {
  it('unwraps the list envelope', async () => {
