  it('encodes the workbook id in the request path', async () => {
    stubFetch();
    fetchMock.mockResolvedValue(jsonResponse(200, { workbook: { id: 'a b' }, worksheets: [] }));

    await api.getWorkbook('a b');
    expect(fetchMock.mock.calls[0][0]).toBe('/api/workbooks/a%20b');
  });
});
