 * Cell value interpretation.
 *
 * `value` is what the user typed and what is persisted; `computed` is the
 * typed value downstream features (sorting, filtering, pivot aggregation) work
 * with; `display` is the string shown in the grid.
 *
 * Until the formula task lands there are no formula results, so a numeric
 * literal becomes a number and everything else stays text. The formula task
 * replaces this module with formula evaluation while keeping the shape.
 */

const NUMERIC_LITERAL = /^-?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/;

export function computeCellValue(rawValue) {
  if (rawValue === null || rawValue === undefined || rawValue === '') {
    return { computed: null, display: '' };
  }
  const text = String(rawValue);
  if (NUMERIC_LITERAL.test(text.trim())) {
    const numeric = Number(text.trim());
    if (Number.isFinite(numeric)) {
      return { computed: numeric, display: text };
    }
  }
  return { computed: text, display: text };
}
