import { inTransaction } from './index.js';

/**
 * Marker recorded in `app_meta` once the evaluation seed has been applied.
 * Bumping the suffix applies a new generation of seed data on next start.
 */
export const SEED_KEY = 'seed:q3-sales:v1';

/** Deterministic id for the seeded workbook, so links are stable across databases. */
export const SEED_WORKBOOK_ID = 'wb-seed-q3-sales';

export const DEFAULT_WORKSHEET_DIMENSIONS = { rowCount: 100, colCount: 26 };

export const SEED_DEFINITION = {
  workbookName: 'Q3 Sales',
  worksheets: [
    {
      name: 'Sheet1',
      cells: [
        { row: 0, col: 0, value: 'Region' },
        { row: 0, col: 1, value: 'Sales' },
        { row: 1, col: 0, value: 'East' },
        { row: 1, col: 1, value: '1200' },
        { row: 2, col: 0, value: 'North' },
        { row: 2, col: 1, value: '800' },
      ],
      validations: [
        {
          type: 'number-between',
          params: { minValue: 0, maxValue: 100 },
          startRow: 2,
          startCol: 1,
          endRow: 9,
          endCol: 1,
        },
      ],
    },
    { name: 'Sheet2', cells: [], validations: [] },
  ],
};

/**
 * Create the initial evaluation data once per database.
 *
 * The seed is idempotent: the marker and all seed rows are written in one
 * transaction, so a restart never duplicates the workbook, never recreates a
 * workbook the user renamed or deleted, and never overwrites user changes. An
 * interrupted seed leaves the database untouched.
 */
export function seedDatabase(db, { now = () => new Date().toISOString(), definition = SEED_DEFINITION } = {}) {
  const applied = db.prepare('SELECT value FROM app_meta WHERE key = ?').get(SEED_KEY);
  if (applied) return { applied: false, workbookId: SEED_WORKBOOK_ID };

  const timestamp = now();
  inTransaction(db, () => {
    db.prepare(
      'INSERT INTO workbooks (id, name, active_worksheet_id, created_at, updated_at) VALUES (?, ?, ?, ?, ?)',
    ).run(SEED_WORKBOOK_ID, definition.workbookName, null, timestamp, timestamp);

    const insertWorksheet = db.prepare(
      `INSERT INTO worksheets (id, workbook_id, name, position, row_count, col_count)
       VALUES (?, ?, ?, ?, ?, ?)`,
    );
    const insertCell = db.prepare('INSERT INTO cells (worksheet_id, row, col, value) VALUES (?, ?, ?, ?)');
    const insertValidation = db.prepare(
      `INSERT INTO validations
         (id, worksheet_id, type, params_json, start_row, start_col, end_row, end_col, position)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    );

    let activeWorksheetId = null;
    definition.worksheets.forEach((worksheet, position) => {
      const worksheetId = randomUUID();
      insertWorksheet.run(
        worksheetId,
        SEED_WORKBOOK_ID,
        worksheet.name,
        position,
        worksheet.rowCount ?? DEFAULT_WORKSHEET_DIMENSIONS.rowCount,
        worksheet.colCount ?? DEFAULT_WORKSHEET_DIMENSIONS.colCount,
      );
      for (const cell of worksheet.cells ?? []) {
        insertCell.run(worksheetId, cell.row, cell.col, cell.value);
      }
      (worksheet.validations ?? []).forEach((validation, index) => {
        insertValidation.run(
          randomUUID(),
          worksheetId,
          validation.type,
          JSON.stringify(validation.params ?? {}),
          validation.startRow,
          validation.startCol,
          validation.endRow,
          validation.endCol,
          index,
        );
      });
      if (activeWorksheetId === null) activeWorksheetId = worksheetId;
    });

    db.prepare('UPDATE workbooks SET active_worksheet_id = ? WHERE id = ?').run(activeWorksheetId, SEED_WORKBOOK_ID);
    db.prepare('INSERT INTO app_meta (key, value) VALUES (?, ?)').run(SEED_KEY, timestamp);
  });

  return { applied: true, workbookId: SEED_WORKBOOK_ID };
}
