import { inTransaction } from '../index.js';
import { computeCellValue } from '../cell-values.js';
import { DEFAULT_WORKSHEET_DIMENSIONS } from '../seed.js';

/**
 * Read and write model for workbooks.
 *
 * Reads return plain JSON-serialisable values in the published shape
 * (docs/api-contract.md): timestamps as ISO-8601 UTC strings, coordinates as
 * zero-based row/col integers, `value` as the raw stored input, `computed` as
 * the typed value and `display` as what the grid shows. Writes go through
 * `inTransaction` so a feature can compose several statements atomically.
 *
 * Invariants kept here:
 * - `workbook.activeWorksheetId` is the single source of truth for the active
 *   worksheet; `worksheet.isActive` is derived while serialising.
 * - `worksheet.lastSelectedCell` is derived from the stored selection focus,
 *   so the current cell and the selection rectangle can never disagree.
 */

export function listWorkbooks(db) {
  const rows = db
    .prepare('SELECT id, name, updated_at FROM workbooks ORDER BY updated_at DESC, name ASC')
    .all();
  return rows.map((row) => ({
    id: row.id,
    name: row.name,
    updatedAt: row.updated_at,
  }));
}

export function getWorkbook(db, workbookId) {
  const row = db
    .prepare('SELECT id, name, active_worksheet_id, created_at, updated_at FROM workbooks WHERE id = ?')
    .get(workbookId);
  if (!row) return null;
  return {
    id: row.id,
    name: row.name,
    activeWorksheetId: row.active_worksheet_id,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export function getWorkbookDetail(db, workbookId) {
  const workbook = getWorkbook(db, workbookId);
  if (!workbook) return null;

  const worksheetRows = db
    .prepare('SELECT * FROM worksheets WHERE workbook_id = ? ORDER BY position ASC')
    .all(workbookId);

  const selectCells = db.prepare('SELECT row, col, value FROM cells WHERE worksheet_id = ? ORDER BY row, col');
  const selectValidations = db.prepare('SELECT * FROM validations WHERE worksheet_id = ? ORDER BY position ASC');

  const worksheets = worksheetRows.map((worksheet) => ({
    id: worksheet.id,
    name: worksheet.name,
    position: worksheet.position,
    isActive: worksheet.id === workbook.activeWorksheetId,
    rowCount: worksheet.row_count,
    colCount: worksheet.col_count,
    lastSelectedCell: { row: worksheet.selection_focus_row, col: worksheet.selection_focus_col },
    lastSelectionRect: {
      anchor: { row: worksheet.selection_anchor_row, col: worksheet.selection_anchor_col },
      focus: { row: worksheet.selection_focus_row, col: worksheet.selection_focus_col },
    },
    cells: selectCells.all(worksheet.id).map((cell) => {
      const { computed, display } = computeCellValue(cell.value);
      return { row: cell.row, col: cell.col, value: cell.value, computed, display };
    }),
    validations: selectValidations.all(worksheet.id).map((validation) => ({
      id: validation.id,
      type: validation.type,
      params: JSON.parse(validation.params_json),
      range: {
        start: { row: validation.start_row, col: validation.start_col },
        end: { row: validation.end_row, col: validation.end_col },
      },
    })),
  }));

  return {
    workbook: {
      id: workbook.id,
      name: workbook.name,
      activeWorksheetId: workbook.activeWorksheetId,
      updatedAt: workbook.updatedAt,
    },
    worksheets,
  };
}

/** Create a workbook with exactly one blank worksheet, which becomes active. */
export function createWorkbook(
  db,
  { name, worksheetName = 'Sheet1', now = () => new Date().toISOString() },
) {
  const timestamp = now();
  const workbookId = randomUUID();
  const worksheetId = randomUUID();

  inTransaction(db, () => {
    db.prepare(
      'INSERT INTO workbooks (id, name, active_worksheet_id, created_at, updated_at) VALUES (?, ?, ?, ?, ?)',
    ).run(workbookId, name, worksheetId, timestamp, timestamp);
    db.prepare(
      `INSERT INTO worksheets (id, workbook_id, name, position, row_count, col_count)
       VALUES (?, ?, ?, ?, ?, ?)`,
    ).run(
      worksheetId,
      workbookId,
      worksheetName,
      0,
      DEFAULT_WORKSHEET_DIMENSIONS.rowCount,
      DEFAULT_WORKSHEET_DIMENSIONS.colCount,
    );
  });

  return getWorkbookDetail(db, workbookId);
}

/** Rename a workbook and bump its last-updated timestamp. Returns null when missing. */
export function renameWorkbook(db, workbookId, name, now = () => new Date().toISOString()) {
  return inTransaction(db, () => {
    const result = db
      .prepare('UPDATE workbooks SET name = ?, updated_at = ? WHERE id = ?')
      .run(name, now(), workbookId);
    if (result.changes === 0) return null;
    return getWorkbookDetail(db, workbookId);
  });
}
