/**
 * Uniform API error handling.
 *
 * Every failing `/api` response is `{ "error": "<message>", "code": "<CODE>" }`
 * with a 4xx/5xx status, matching the contract published in
 * docs/api-contract.md. `error` is the message shown to the user; `code` is the
 * stable identifier feature tasks branch on.
 */
export class ApiError extends Error {
  constructor(status, message, { code = 'ERROR', expose = true } = {}) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.code = code;
    this.expose = expose;
  }
}

export function apiNotFoundHandler(req, res) {
  res.status(404).json({
    error: `Not found: ${req.method} ${req.originalUrl}`,
    code: 'ROUTE_NOT_FOUND',
  });
}

// Express identifies error middleware by arity
// eslint-disable-next-line no-unused-vars
export function errorHandler(error, req, res, next) {
  const status = Number.isInteger(error?.status) ? error.status : 500;
  const expose = error instanceof ApiError ? error.expose : false;
  const message = expose ? error.message : 'Internal server error';
  const code = error instanceof ApiError ? error.code : 'INTERNAL_ERROR';
  if (status >= 500) {
    console.error('[api] unhandled error', error);
  }
  res.status(status).json({ error: message, code });
}
