import {
  createWorkbook,
  getWorkbookDetail,
  listWorkbooks,
  renameWorkbook,
} from '../db/repositories/workbooks.js';
import { ApiError } from '../http/errors.js';
import { requireWorkbookName } from '../http/validation.js';

/** Default name for a workbook created without one (Google-Sheets-style). */
export const DEFAULT_WORKBOOK_NAME = 'Untitled spreadsheet';

function workbookNotFound() {
  return new ApiError(404, 'Workbook not found', { code: 'WORKBOOK_NOT_FOUND' });
}

/**
 * Workbook endpoints shared by every feature task.
 *
 * Response shapes are the published contract in docs/api-contract.md; feature
 * tasks add their own routers and keep these shapes for the endpoints below.
 */
export function createWorkbooksRouter(db) {
  const router = express.Router();

  router.get('/', (req, res) => {
    res.json({ workbooks: listWorkbooks(db) });
  });

  router.post('/', (req, res) => {
    const requestedName = req.body && typeof req.body.name !== 'undefined' ? requireWorkbookName(req.body.name) : DEFAULT_WORKBOOK_NAME;
    const detail = createWorkbook(db, { name: requestedName });
    res.status(201).json(detail);
  });

  router.get('/:id', (req, res) => {
    const detail = getWorkbookDetail(db, req.params.id);
    if (!detail) throw workbookNotFound();
    res.json(detail);
  });

  router.patch('/:id', (req, res) => {
    const name = requireWorkbookName(req.body?.name);
    const detail = renameWorkbook(db, req.params.id, name);
    if (!detail) throw workbookNotFound();
    res.json(detail);
  });

  return router;
}
