    expect(Array.isArray(body.workbooks)).toBe(true);

    const seeded = body.workbooks.find((workbook) => workbook.name === 'Q3 Sales');
    expect(seeded).toBeDefined();
    expect(typeof seeded.id).toBe('string');
    expect(seeded.updatedAt).toMatch(ISO_UTC);
  });

  it('returns workbook, worksheet dimensions and typed cell values for the seeded workbook', async () => {
    const list = await (await fetch(`${server.baseUrl}/api/workbooks`)).json();
    const seeded = list.workbooks.find((workbook) => workbook.name === 'Q3 Sales');

    const response = await fetch(`${server.baseUrl}/api/workbooks/${seeded.id}`);
    expect(response.status).toBe(200);
    const body = await response.json();

    expect(body.workbook).toMatchObject({ id: seeded.id, name: 'Q3 Sales' });
    expect(body.workbook.updatedAt).toMatch(ISO_UTC);

    const sheetNames = body.worksheets.map((worksheet) => worksheet.name);
    expect(sheetNames).toEqual(['Sheet1', 'Sheet2']);

    const sheet1 = body.worksheets[0];
    expect(sheet1.position).toBe(0);
    expect(sheet1.isActive).toBe(true);
    expect(sheet1.rowCount).toBe(100);
    expect(sheet1.colCount).toBe(26);
    expect(body.workbook.activeWorksheetId).toBe(sheet1.id);
    expect(sheet1.lastSelectedCell).toEqual(sheet1.lastSelectionRect.focus);

    expect(sheet1.validations).toEqual([
      expect.objectContaining({
        type: 'number-between',
        params: { minValue: 0, maxValue: 100 },
        range: { start: { row: 2, col: 1 }, end: { row: 9, col: 1 } },
      }),
    ]);

    const cellAt = (row, col) => sheet1.cells.find((entry) => entry.row === row && entry.col === col);
    expect(cellAt(0, 0)).toMatchObject({ value: 'Region', computed: 'Region', display: 'Region' });
    expect(cellAt(0, 1)).toMatchObject({ value: 'Sales', computed: 'Sales' });
