import { prepareDatabase, startTestServer, testApp } from './helpers.js';

/**
 * Write-path conventions every feature task reuses: JSON body, transactional
 * writes, `{ error, code }` failures, and a last-updated timestamp that moves
 * when the workbook changes.
 */
describe('workbook write API contract', () => {
  let context;
  let server;

  beforeAll(async () => {
    context = prepareDatabase();
    server = await startTestServer(testApp(context.db));
  });

  afterAll(async () => {
    await server.close();
    context.cleanup();
  });

  async function postWorkbook(body) {
    return fetch(`${server.baseUrl}/api/workbooks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
  }

  it('creates a workbook with a single blank active worksheet', async () => {
    const response = await postWorkbook({ name: '  Fresh workbook  ' });
    expect(response.status).toBe(201);
    const detail = await response.json();

    expect(detail.workbook.name).toBe('Fresh workbook');
    expect(detail.worksheets).toHaveLength(1);
    expect(detail.worksheets[0]).toMatchObject({ name: 'Sheet1', position: 0, isActive: true, cells: [] });
    expect(detail.workbook.activeWorksheetId).toBe(detail.worksheets[0].id);

    const list = await (await fetch(`${server.baseUrl}/api/workbooks`)).json();
    expect(list.workbooks.map((workbook) => workbook.name)).toContain('Fresh workbook');
  });

  it('creates an unnamed workbook with the default name', async () => {
    const response = await postWorkbook({});
    expect(response.status).toBe(201);
    expect((await response.json()).workbook.name).toBe('Untitled spreadsheet');
  });

  it('rejects an empty workbook name without creating a record', async () => {
    const before = (await (await fetch(`${server.baseUrl}/api/workbooks`)).json()).workbooks.length;

    const response = await postWorkbook({ name: '   ' });
    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: 'Workbook name cannot be empty',
      code: 'WORKBOOK_NAME_EMPTY',
    });

    const after = (await (await fetch(`${server.baseUrl}/api/workbooks`)).json()).workbooks.length;
    expect(after).toBe(before);
  });

  it('renames a workbook, trims the name and bumps last updated', async () => {
    const created = await (await postWorkbook({ name: 'Before rename' })).json();
    const workbookId = created.workbook.id;

    const response = await fetch(`${server.baseUrl}/api/workbooks/${workbookId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: '  After rename  ' }),
    });
    expect(response.status).toBe(200);
    const detail = await response.json();
    expect(detail.workbook.name).toBe('After rename');
    expect(new Date(detail.workbook.updatedAt).getTime()).toBeGreaterThanOrEqual(
      new Date(created.workbook.updatedAt).getTime(),
    );

    const reread = await (await fetch(`${server.baseUrl}/api/workbooks/${workbookId}`)).json();
    expect(reread.workbook.name).toBe('After rename');
    const list = await (await fetch(`${server.baseUrl}/api/workbooks`)).json();
    expect(list.workbooks.find((workbook) => workbook.id === workbookId).name).toBe('After rename');
  });

  it('rejects an empty rename and keeps the previous name', async () => {
    const created = await (await postWorkbook({ name: 'Keep me' })).json();
    const workbookId = created.workbook.id;

    const response = await fetch(`${server.baseUrl}/api/workbooks/${workbookId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: ' ' }),
    });
    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: 'Workbook name cannot be empty',
      code: 'WORKBOOK_NAME_EMPTY',
    });

    const reread = await (await fetch(`${server.baseUrl}/api/workbooks/${workbookId}`)).json();
    expect(reread.workbook.name).toBe('Keep me');
  });

  it('answers a rename of an unknown workbook with the shared error contract', async () => {
    const response = await fetch(`${server.baseUrl}/api/workbooks/missing`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: 'Whatever' }),
    });
    expect(response.status).toBe(404);
    expect(await response.json()).toEqual({ error: 'Workbook not found', code: 'WORKBOOK_NOT_FOUND' });
  });
});
