/**
 * Uniform API access.
 *
 * Every request is same-origin and relative (`/api/...`); development traffic is
 * proxied to the backend. Failures always surface the backend's `{ error }`
 * message through ApiError so screens can show it next to the control that
 * triggered the call.
 */
export class ApiError extends Error {
  readonly status: number;
  readonly code: string | null;

  constructor(status: number, message: string, code: string | null = null) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.code = code;
  }
}

function readErrorBody(body: unknown): { message: string | null; code: string | null } {
  if (!body || typeof body !== 'object') return { message: null, code: null };
  const record = body as { error?: unknown; code?: unknown };
  return {
    message: typeof record.error === 'string' && record.error.length > 0 ? record.error : null,
    code: typeof record.code === 'string' && record.code.length > 0 ? record.code : null,
  };
}

export async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
  let response: Response;
  try {
    response = await fetch(path, {
      headers: { Accept: 'application/json', ...(init?.body ? { 'Content-Type': 'application/json' } : {}) },
      ...init,
    });
  } catch (cause) {
    throw new ApiError(0, cause instanceof Error ? cause.message : 'Network request failed');
  }

  const text = await response.text();
  let body: unknown;
  if (text.length > 0) {
    try {
      body = JSON.parse(text);
    } catch {
      body = undefined;
    }
  }

  if (!response.ok) {
    const { message, code } = readErrorBody(body);
    throw new ApiError(response.status, message ?? `Request failed with status ${response.status}`, code);
  }
  return body as T;
}

export const api = {
  health: () => apiFetch<HealthResponse>('/api/health'),

  async listWorkbooks(): Promise<WorkbookSummary[]> {
    const body = await apiFetch<WorkbookListResponse>('/api/workbooks');
    return body.workbooks ?? [];
  },

  getWorkbook: (workbookId: string) =>
    apiFetch<WorkbookDetail>(`/api/workbooks/${encodeURIComponent(workbookId)}`),

  /** Create a workbook; without a name the backend uses its default name. */
  createWorkbook: (name?: string) =>
    apiFetch<WorkbookDetail>('/api/workbooks', {
      method: 'POST',
      body: JSON.stringify(typeof name === 'undefined' ? {} : { name }),
    }),

  renameWorkbook: (workbookId: string, name: string) =>
    apiFetch<WorkbookDetail>(`/api/workbooks/${encodeURIComponent(workbookId)}`, {
      method: 'PATCH',
      body: JSON.stringify({ name }),
    }),
};
