  const [selectedWorksheetId, setSelectedWorksheetId] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setState({ status: 'loading' });
    setSelectedWorksheetId(null);
    api
      .getWorkbook(workbookId)
      .then((detail) => {
        if (!cancelled) setState({ status: 'ready', detail });
      })
      .catch((error: unknown) => {
        if (!cancelled) {
          setState({ status: 'error', message: error instanceof Error ? error.message : 'Failed to open workbook' });
        }
      });
    return () => {
      cancelled = true;
    };
  }, [workbookId]);

  if (state.status === 'loading') {
    return (
      <main className="p-8">
        <p role="status">Loading workbook…</p>
      </main>
    );
  }

  if (state.status === 'error') {
    return (
      <main className="p-8">
        <p role="alert" className="text-danger">
          {state.message}
        </p>
        <p className="mt-4">
          <Link to="/" className="sw-link">
            Back to workbooks
          </Link>
        </p>
      </main>
    );
  }

  const { workbook, worksheets } = state.detail;
  const activeWorksheet =
    worksheets.find((worksheet) => worksheet.id === selectedWorksheetId) ??
    worksheets.find((worksheet) => worksheet.isActive) ??
    worksheets[0];

  return (
    <main className="flex h-full flex-col">
      <header className="flex items-baseline gap-4 border-b border-border bg-surface px-6 py-3">
        <h1 className="text-xl">{workbook.name}</h1>
        <span className="text-ink-muted">{lastUpdatedText(workbook.updatedAt)}</span>
      </header>

      {activeWorksheet ? (
        <Tabs.Root
          value={activeWorksheet.id}
          onValueChange={setSelectedWorksheetId}
          className="flex flex-1 flex-col overflow-hidden"
        >
          <Tabs.List
            aria-label="Worksheets"
            className="flex gap-1 border-b border-border bg-header px-4 pt-2"
          >
            {worksheets.map((worksheet) => {
              const isActive = worksheet.id === activeWorksheet.id;
              return (
                <Tabs.Trigger
                  key={worksheet.id}
                  value={worksheet.id}
                  className={`rounded-t px-3 py-1.5 sw-focus ${
                    isActive ? 'bg-surface text-ink' : 'bg-transparent text-ink-muted hover:bg-accent-soft'
                  }`}
                >
                  {worksheet.name}
                </Tabs.Trigger>
              );
            })}
          </Tabs.List>

          <Tabs.Content value={activeWorksheet.id} className="flex-1 overflow-auto p-4">
            <WorkbookGrid
              cells={activeWorksheet.cells}
              selectedCell={activeWorksheet.lastSelectedCell}
              selectionRect={activeWorksheet.lastSelectionRect}
              rowCount={activeWorksheet.rowCount}
              colCount={activeWorksheet.colCount}
            />
          </Tabs.Content>
        </Tabs.Root>
      ) : (
        <p role="status" className="p-6">
          This workbook has no worksheets.
        </p>
      )}
    </main>
  );
}
