    await editorHeading.waitFor({ state: 'visible', timeout: 30000 });
    const editorUpdatedText = text(await page.getByText(/Last updated:/).first().innerText());
    check('editor shows the same Last updated value as the home page', editorUpdatedText === homeUpdatedText, `${homeUpdatedText} vs ${editorUpdatedText}`);

    const grid = page.getByRole('grid', { name: 'Worksheet grid' });
    await grid.waitFor({ state: 'visible', timeout: 30000 });
    check('grid accessible name is "Worksheet grid"', (await grid.count()) === 1);
    check(
      'grid exposes aria-multiselectable="true"',
      (await grid.getAttribute('aria-multiselectable')) === 'true',
    );

    const cellText = async (locator) => text(await locator.textContent());
