    for (const [address, expected] of Object.entries(seededValues)) {
      const value = await cellText(grid.getByRole('gridcell', { name: address, exact: true }));
      check(`editor grid ${address} = ${expected}`, value === expected, `got "${value}"`);
    }

    const activeTab = page.getByRole('tab', { name: 'Sheet1', exact: true });
    check('Sheet1 tab exists and is selected', (await activeTab.getAttribute('aria-selected')) === 'true');
    check(
      'all worksheets are exposed as tabs',
      (await page.getByRole('tab').count()) === 2,
      `count ${await page.getByRole('tab').count()}`,
    );
    await page.screenshot({ path: path.join(ARTIFACTS, 'editor.png'), fullPage: true });

